using System.Diagnostics;
using System.Text.Json;
using StardewModdingAPI;
using StardewThor.Bridge;
using StardewValley;

namespace StardewThor.ReadOnly;
internal sealed class ProgressCollector {
 private readonly int owner=Environment.CurrentManagedThreadId;private IEnumerator<bool>? work;private long version=1,completedAt;private string language="",fingerprint="";
 public DemandDocument Document{get;}=new(new PlayerProgress(1,Array.Empty<string>(),Array.Empty<string>(),new(0,0,0,0,0,0,0),new(),0,Array.Empty<string>(),"building"),512*1024);
 public void Invalidate(string lang){if(Environment.CurrentManagedThreadId!=owner)throw new InvalidOperationException("Game thread required");work?.Dispose();work=null;language=lang;fingerprint="";completedAt=0;Document.Publish(new PlayerProgress(++version,Array.Empty<string>(),Array.Empty<string>(),new(0,0,0,0,0,0,0),new(),0,Array.Empty<string>(),"building",lang));}
 public void Refresh(){if(work==null)completedAt=0;}
 public void Tick(string lang){if(Environment.CurrentManagedThreadId!=owner)throw new InvalidOperationException("Game thread required");if(lang!=language)Invalidate(lang);if(!Context.IsWorldReady){if(fingerprint!="unavailable"){fingerprint="unavailable";Document.Publish(new PlayerProgress(++version,Array.Empty<string>(),Array.Empty<string>(),new(0,0,0,0,0,0,0),new(),0,Array.Empty<string>(),"unavailable",lang));}return;}if(work==null&&BridgeServer.Age(completedAt)<3000)return;work??=Collect().GetEnumerator();var watch=Stopwatch.StartNew();try{for(int i=0;i<64&&watch.Elapsed.TotalMilliseconds<1.5;i++)if(!work.MoveNext()){work.Dispose();work=null;completedAt=Stopwatch.GetTimestamp();return;}}catch{work?.Dispose();work=null;completedAt=Stopwatch.GetTimestamp();Document.Publish(new PlayerProgress(++version,Array.Empty<string>(),Array.Empty<string>(),new(0,0,0,0,0,0,0),new(),0,new[]{"progress-source-changed"},"unsupported",lang));}}
 private IEnumerable<bool> Collect(){var limited=new HashSet<string>(StringComparer.Ordinal);var player=Game1.player;var known=new SortedSet<string>(StringComparer.Ordinal);var met=new SortedSet<string>(StringComparer.Ordinal);int knownBytes=0,metBytes=0,mapBytes=0;foreach(var id in player.friendshipData.Keys){if(met.Count>=512){limited.Add("progress-npcs-limit");break;}if(id.Length>160){limited.Add("progress-id-limit");continue;}if(metBytes+JsonBytes(id)>64*1024){limited.Add("progress-npcs-bytes");break;}metBytes+=JsonBytes(id);met.Add(id);yield return true;}
  int[] counts=new int[7];IEnumerable<string>[] sources={player.basicShipped.Keys,player.fishCaught.Keys,player.mineralsFound.Keys,player.archaeologyFound.Keys,player.recipesCooked.Keys};for(int source=0;source<sources.Length;source++){var seen=new HashSet<string>(StringComparer.Ordinal);int scanned=0;foreach(var id in sources[source]){if(++scanned>16384){limited.Add("progress-source-limit");break;}var q=Qualified(id,limited);if(q!=null){Add(known,q,limited,ref knownBytes);seen.Add(q);}yield return true;}counts[source]=seen.Count;}
  var recipeItems=new HashSet<string>(StringComparer.Ordinal);foreach(bool cooking in new[]{true,false}){var recipes=cooking?DataLoader.CookingRecipes(Game1.content):DataLoader.CraftingRecipes(Game1.content);var learned=cooking?player.cookingRecipes:player.craftingRecipes;int n=0;foreach(var recipeId in learned.Keys){if(n++>=4096){limited.Add("progress-recipes-limit");break;}if(recipes.TryGetValue(recipeId,out var raw)){var recipe=ReadOnlyMetadata.Recipe(raw,cooking,limited);if(recipe!=null)foreach(var id in recipe.Value.Outputs){Add(known,id,limited,ref knownBytes);if(recipeItems.Count<8192)recipeItems.Add(id);else limited.Add("progress-recipes-items-limit");}}else limited.Add("progress-recipe-unknown");yield return true;}}counts[5]=recipeItems.Count;
  var owned=new HashSet<string>(StringComparer.Ordinal);int inventory=0;foreach(var item in player.Items.Concat(new Item?[]{player.hat.Value,player.shirtItem.Value,player.pantsItem.Value,player.boots.Value,player.leftRing.Value,player.rightRing.Value,player.CurrentTool}).Concat(player.trinketItems)){if(inventory++>=256){limited.Add("progress-owned-limit");break;}if(item!=null){var id=item.QualifiedItemId;if(id.Length<=160){Add(known,id,limited,ref knownBytes);owned.Add(id);}else limited.Add("progress-id-limit");}yield return true;}counts[6]=owned.Count;
  int gifts=0;foreach(var npc in player.giftedItems){foreach(var gift in npc.Value.Keys){if(gifts++>=16384){limited.Add("progress-gifts-limit");break;}var id=Qualified(gift,limited);if(id!=null)Add(known,id,limited,ref knownBytes);yield return true;}if(gifts>=16384)break;}
  var areas=new Dictionary<string,bool>(StringComparer.Ordinal);foreach(var region in DataLoader.WorldMap(Game1.content)){if(areas.Count>=512){limited.Add("progress-map-limit");break;}bool visible=region.Value.BaseTexture.Count==0||region.Value.BaseTexture.Take(64).Any(t=>SafeProgressQuery.Check(t.Condition,limited));if(region.Value.BaseTexture.Count>64)limited.Add("progress-map-texture-limit");if(region.Key.Length>160||mapBytes+JsonBytes(region.Key)+8>64*1024){limited.Add("progress-map-bytes");continue;}mapBytes+=JsonBytes(region.Key)+8;areas[region.Key]=visible;yield return true;int count=0;foreach(var area in region.Value.MapAreas){if(count++>=128||areas.Count>=512){limited.Add("progress-map-limit");break;}string key=region.Key+"/"+area.Id;if(key.Length>160){limited.Add("progress-id-limit");continue;}if(mapBytes+JsonBytes(key)+8>64*1024){limited.Add("progress-map-bytes");break;}mapBytes+=JsonBytes(key)+8;areas[key]=visible&&SafeProgressQuery.Check(area.Condition,limited);yield return true;}}
  using var hash=System.Security.Cryptography.IncrementalHash.CreateHash(System.Security.Cryptography.HashAlgorithmName.SHA256);void Append(string text)=>hash.AppendData(System.Text.Encoding.UTF8.GetBytes(text+"\0"));foreach(var id in met){Append("met:"+id);yield return true;}foreach(var id in known){Append("item:"+id);yield return true;}foreach(var area in areas.OrderBy(p=>p.Key,StringComparer.Ordinal)){Append("map:"+area.Key+"="+area.Value);yield return true;}var notes=limited.OrderBy(x=>x,StringComparer.Ordinal).Take(16).ToArray();Append(string.Join(',',counts));Append(player.eventsSeen.Count.ToString());Append(string.Join('|',notes));string next=Convert.ToHexString(hash.GetHashAndReset());if(next!=fingerprint){fingerprint=next;Document.Publish(new PlayerProgress(++version,met.ToArray(),known.ToArray(),new(counts[0],counts[1],counts[2],counts[3],counts[4],counts[5],counts[6]),areas,player.eventsSeen.Count,notes,"ready",language));}
 }
 private static string? Qualified(string id,ISet<string> limited){if(id.Length>160){limited.Add("progress-id-limit");return null;}var q=ItemRegistry.QualifyItemId(id);if(q==null||q.Length>160){limited.Add("progress-item-unknown");return null;}return q;}
 private static int JsonBytes(string value)=>System.Text.Encoding.UTF8.GetByteCount(JsonSerializer.Serialize(value,BridgeServer.Json))+1;
 private static void Add(ISet<string> known,string id,ISet<string> limited,ref int bytes){if(known.Contains(id))return;if(known.Count>=8192){limited.Add("progress-items-limit");return;}int size=JsonBytes(id);if(bytes+size>256*1024){limited.Add("progress-items-bytes");return;}bytes+=size;known.Add(id);}
}
